[{"order":1,"type":"heading","text":"Monitoring, Alerting, and Incident Response for Smart Contracts"},{"order":2,"type":"paragraph","text":"Deploying smart contracts to production is only half the battle. Because blockchain transactions are immutable and exploits happen in seconds, continuous monitoring, proactive alerting, and rapid incident response are critical components of secure Web3 development. This tutorial explores how to leverage Forta and Tenderly to protect decentralized applications."},{"order":3,"type":"heading","text":"Prerequisites"},{"order":4,"type":"bullet_point","text":"Basic understanding of Ethereum and smart contract architecture."},{"order":5,"type":"bullet_point","text":"Familiarity with JavaScript, TypeScript, or Python."},{"order":6,"type":"bullet_point","text":"Active accounts on Forta and Tenderly."},{"order":7,"type":"heading","text":"1. Understanding Forta for Decentralized Runtime Monitoring"},{"order":8,"type":"paragraph","text":"Forta is a decentralized runtime security network that detects threats and anomalies on smart contracts in real-time. It operates via detection bots written by the community and developers. These bots monitor transactions and emit alerts when suspicious patterns occur."},{"order":9,"type":"subheading","text":"Writing a Custom Forta Bot"},{"order":10,"type":"paragraph","text":"Below is a basic TypeScript Forta bot that listens for large withdrawals from a specific vault contract and raises an alert if the threshold is breached."},{"order":11,"type":"code","text":"import { Finding, FindingSeverity, FindingType, HandleTransaction, TransactionEvent } from 'forta-agent';

const VAULT_ADDRESS = '0x1234567890abcdef1234567890abcdef12345678';
const WITHDRAW_SIGNATURE = 'Withdraw(address,uint256)';
const THRESHOLD = 1000000000000000000000n; // 1000 tokens

const provideHandleTransaction = (): HandleTransaction => {
  return async (txEvent: TransactionEvent) => {
    const findings: Finding[] = [];
    const logs = txEvent.filterLog(WITHDRAW_SIGNATURE, VAULT_ADDRESS);

    for (const log of logs) {
      const { amount } = log.args;
      if (BigInt(amount) >= THRESHOLD) {
        findings.push(
          Finding.from({
            name: 'Large Withdrawal Detected',
            description: 'A withdrawal exceeding the threshold was executed.',
            alertId: 'FORTA-VAULT-LARGE-WITHDRAWAL',
            severity: FindingSeverity.High,
            type: FindingType.Suspicious,
            metadata: { amount: amount.toString() },
          })
        );
      }
    }
    return findings;
  };
};

export default {
  handleTransaction: provideHandleTransaction(),
};"},{"order":12,"type":"heading","text":"2. Using Tenderly for Real-Time Alerting and Debugging"},{"order":13,"type":"paragraph","text":"While Forta excels at decentralized behavior analysis, Tenderly provides a comprehensive Web3 development platform with powerful transaction simulation, monitoring, and alerting capabilities. Tenderly Alerts allow you to trigger webhooks, Discord notifications, or Telegram messages based on contract events or state changes."},{"order":14,"type":"subheading","text":"Setting Up Tenderly Webhooks"},{"order":15,"type":"paragraph","text":"To integrate Tenderly alerts with your incident response system (like PagerDuty or a custom backend), configure a webhook endpoint to receive payloads whenever an alert rule triggers."},{"order":16,"type":"code","text":"// Example Express.js webhook receiver for Tenderly alerts
const express = require('express');
const app = express();

app.use(express.json());

app.post('/tenderly-webhook', (req, res) => {
  const alertData = req.body;
  console.log('Incident Alert Received from Tenderly:', alertData.name);

  // Trigger internal incident response workflow
  triggerIncidentResponse(alertData);

  res.status(200).send('Webhook received successfully');
});

function triggerIncidentResponse(data) {
  // Logic to pause contracts or notify security team
  console.log('Executing automated safety protocols for transaction:', data.transactionId);
}

app.listen(3000, () => console.log('Webhook server running on port 3000'));"},{"order":17,"type":"heading","text":"3. Incident Response Playbook for Web3"},{"order":18,"type":"paragraph","text":"When an alert fires from Forta or Tenderly, time is of the essence. Having a predefined incident response playbook minimizes potential losses."},{"order":19,"type":"bullet_point","text":"Step 1: Verification - Automatically or manually verify if the alert is a false positive using Tenderly Simulation."},{"order":20,"type":"bullet_point","text":"Step 2: Containment - Execute emergency pause functions (e.g., OpenZeppelin Pausable) if protocol funds are at risk."},{"order":21,"type":"bullet_point","text":"Step 3: Eradication and Analysis - Use Tenderly Debugger to step through the exploit transaction and identify the root cause."},{"order":22,"type":"bullet_point","text":"Step 4: Post-Mortem - Communicate transparently with your community and implement fixes before resuming protocol operations."},{"order":23,"type":"heading","text":"Conclusion"},{"order":24,"type":"paragraph","text":"Combining Forta and Tenderly provides a robust defense-in-depth strategy for smart contract security. By pairing decentralized runtime monitoring with real-time alerts and instantaneous debugging tools, your protocol will be well-equipped to detect and neutralize threats before catastrophic losses occur."}]
